script:
(function () {
  'use strict';
  // Student loan interest deduction (IRC 221) for tax year 2026.
  //   Deduction before phase-out = min(interest paid, $2,500)
  //   Phase-out: reduced by deduction x (MAGI - start) / (end - start), capped at the full amount
  //   Not allowed for married filing separately or if someone can claim you as a dependent.
  //   Tax saved = federal tax without the deduction - federal tax with it (the deduction lowers
  //   AGI, which is then reduced by the standard deduction), plus state rate x deduction.
  //   After-tax loan rate = loan rate x (1 - total tax saved / interest paid).
  // Verified (Node, scratch tests): single, MAGI $60,000, $1,500 interest: deduction $1,500,
  // federal tax $5,020 -> $4,840, saved $180 (12%); 6% loan -> 5.28% after tax. Phase-out:
  // single $90,000 with $3,000 paid -> $1,666.67; joint $190,000 -> $1,250; single $100,000,
  // MFS and dependents -> $0. Phase-out figures checked against Rev. Proc. 2025-32 sec. 4.29.
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rates: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200;               // per child under 17
  var OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // Student loan interest: $2,500 cap (IRC 221(b)(1)); 2026 MAGI phase-out ranges from
  // Rev. Proc. 2025-32 section 4.29: $85,000-$100,000 ($175,000-$205,000 joint).
  var SLI_MAX = 2500;
  var SLI_PHASEOUT = { single: [85000, 100000], hoh: [85000, 100000], mfj: [175000, 205000] };
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) {
        tax += (Math.min(taxable, upper) - lower) * RATES[i];
        marginal = RATES[i];
      }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual federal income tax: AGI - standard deduction - extra deductions, brackets, then
  // non-refundable child / dependent credits (refundable part of the child credit not modelled).
  function federalTax(agi, status, kids, otherDeps, extraDeduction) {
    var taxable = Math.max(0, agi - STANDARD_DEDUCTION[status] - (extraDeduction || 0));
    var bt = bracketTax(taxable, BRACKETS[status]);
    var credits = kids * CHILD_CREDIT + otherDeps * OTHER_DEPENDENT_CREDIT;
    var over = Math.max(0, agi - CREDIT_PHASEOUT_START[status]);
    credits = Math.max(0, credits - Math.ceil(over / 1000) * 50);
    return { taxable: taxable, tax: Math.max(0, bt.tax - credits), marginal: bt.marginal };
  }

  function ficaTax(wages) {
    var ss = SS_RATE * Math.min(wages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * wages + ADDL_MEDICARE_RATE * Math.max(0, wages - ADDL_MEDICARE_WITHHOLD_START);
    return { ss: ss, medicare: medicare };
  }

  function allowedDeduction(interest, magi, status, dependent) {
    if (dependent || !SLI_PHASEOUT[status]) return 0;
    var base = Math.min(interest, SLI_MAX);
    var range = SLI_PHASEOUT[status];
    var fraction = Math.min(1, Math.max(0, magi - range[0]) / (range[1] - range[0]));
    return Math.max(0, base - base * fraction);
  }

  function compute(o) {
    var deduction = allowedDeduction(o.interest, o.magi, o.status, o.dependent);
    var without = federalTax(o.magi, o.status, o.kids, 0, 0);
    var withD = federalTax(o.magi - deduction, o.status, o.kids, 0, 0);
    var fedSaved = Math.max(0, without.tax - withD.tax);
    var stateSaved = o.stateRate / 100 * deduction;
    var saved = fedSaved + stateSaved;
    var afterTaxInterest = Math.max(0, o.interest - saved);
    return { deduction: deduction, without: without, withD: withD, fedSaved: fedSaved,
             stateSaved: stateSaved, saved: saved, afterTaxInterest: afterTaxInterest,
             afterTaxRate: o.interest > 0 ? o.loanRate * afterTaxInterest / o.interest : o.loanRate };
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var o = {
      status: document.getElementById('slStatus').value, magi: num('slIncome'), interest: num('slInterest'),
      dependent: document.getElementById('slDependent').checked, kids: Math.round(num('slKids')),
      stateRate: num('slState'), loanRate: num('slRate')
    };
    if (!BRACKETS[o.status]) o.status = 'single';
    var error = document.getElementById('slError');
    var nums = [o.magi, o.interest, o.kids, o.stateRate, o.loanRate];
    var bad = nums.some(function (v) { return !isFinite(v) || v < 0; }) || o.magi > 1e9 ||
              o.interest > 1e7 || o.kids > 20 || o.stateRate > 20 || o.loanRate > 50;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, a state rate from 0 to 20% and a loan rate from 0 to 50%.';
      return;
    }

    var r = compute(o);
    setText('slDeduction', money.format(r.deduction));
    setText('slSaved', money.format(r.saved));
    setText('slAfterRate', pct.format(r.afterTaxRate / 100));
    setText('slFedSaved', money.format(r.fedSaved));
    setText('slStateSaved', money.format(r.stateSaved));
    setText('slAfterInterest', money.format(r.afterTaxInterest));
    setText('slMarginal', pct.format(r.withD.marginal));
    var range = SLI_PHASEOUT[o.status];
    setText('slRange', range ? whole.format(range[0]) + ' to ' + whole.format(range[1]) : 'Not available');
    setText('slTaxable', money.format(r.withD.taxable));

    var reason = '';
    if (o.dependent) reason = 'You cannot take this deduction if someone can claim you as a dependent.';
    else if (o.status === 'mfs') reason = 'Married couples filing separately cannot take the student loan interest deduction.';
    else if (o.interest > SLI_MAX && r.deduction > 0) reason = 'Only the first ' + whole.format(SLI_MAX) + ' of interest paid in a year can be deducted.';
    else if (o.interest > 0 && r.deduction === 0) reason = 'Your income is at or above the end of the ' + TAX_YEAR + ' phase-out range, so the deduction is fully phased out.';
    else if (o.interest > 0 && r.deduction < Math.min(o.interest, SLI_MAX)) reason = 'Your income is inside the ' + TAX_YEAR + ' phase-out range, so part of the deduction is lost.';
    if (r.deduction > 0 && r.fedSaved === 0) reason += (reason ? ' ' : '') + 'Your federal tax is already zero, so the deduction saves no federal tax this year.';
    var noteEl = document.getElementById('slNote');
    noteEl.hidden = !reason;
    noteEl.textContent = reason;
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('slForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
